package capschema

// MediaGroupID is a device's membership in a multiroom group: the server computes each member's config from the
// group it stores (groups and group_members) and pushes it, with the group key as the groupKey secret. a device with
// no group gets {"enabled":false}. the device hands it to audiod as GroupConfig (cadence/audiod/v1), which streams
// cadence/sync/v1 between the members.
const MediaGroupID = "media.group"

// MediaGroupKeySecret is media.group's one secret: the group key, 64 lowercase hex characters (32 bytes), generated by
// the server per group and changed when the group's membership changes.
const MediaGroupKeySecret = "groupKey"

// bounds both sides share
const (
	GroupLatencyMinMs     = 200
	GroupLatencyMaxMs     = 5000
	GroupLatencyDefaultMs = 1000
	GroupTrimMinMs        = -500
	GroupTrimMaxMs        = 500
	// a calibration's trim, to the microsecond: when set it is the trim and trimMs is its value rounded
	GroupTrimMinUs      = -500_000
	GroupTrimMaxUs      = 500_000
	GroupBitrateMinKbps = 64
	GroupBitrateMaxKbps = 510
	GroupMaxMembers     = 8
	// the port a leader binds, tcp (stream) and udp (clock)
	GroupDefaultPort = 7701
)

// group roles, channels and states as media.group's json spells them
const (
	GroupRoleLeader = "leader"
	GroupRoleMember = "member"

	GroupChannelBoth  = "both"
	GroupChannelLeft  = "left"
	GroupChannelRight = "right"
	GroupChannelMono  = "mono"
)

// the clock budget (us) of each group kind: a stereo pair's two speakers must agree within 100 us, speakers in one
// room within a millisecond, rooms within 5
const (
	GroupBudgetPairUs  = 100
	GroupBudgetRoomUs  = 1000
	GroupBudgetHouseUs = 5000
)

// GroupSourceGraceMs is how long a group's leader that stopped playing a source of its own (localSource) keeps the
// lead before it falls back to the group's clock master: a pause or the next episode does not move it.
const GroupSourceGraceMs = 30_000

// MediaGroupConfig is media.group's config. enabled false needs nothing else. a leader needs groupId, role, latencyMs
// and members (the other members' device ids); a member needs groupId, role, leader (its lan address and port) and
// latencyMs. budgetUs defaults to 1000, channel to both, trimMs to 0, bitrateKbps to 256. trimUs, when non-zero, is
// the trim to the microsecond (a calibration's) and trimMs is not read. clock, when set, is the clock master's lan
// address and port (the port the group's stream uses): another device serves the group clock, so a leader dials it as
// a member does and a member dials it for its clock and leader for the stream; clockMaster: this device serves the
// clock (udp on the group's port) although it is not the leader, and wins over clock. neither set: the leader serves
// the clock, as before both existed. a leader's autoLatency tunes the latency itself
// (latencyMs is where it starts), autoBitrate steps the opus bitrate down while a member falls behind (bitrateKbps is
// the ceiling), autoWait sets the start wait from the members' ready times (waitMs is the ceiling).
const MediaGroupConfig = `{"type":"object","properties":{` +
	`"enabled":{"type":"boolean"},` +
	`"groupId":{"type":"string","minLength":1,"maxLength":64},` +
	`"role":{"enum":["leader","member"]},` +
	`"leader":{"type":"object","properties":{` +
	`"host":{"type":"string","minLength":1,"maxLength":64},` +
	`"port":{"type":"integer","minimum":1,"maximum":65535}` +
	`},"required":["host","port"],"additionalProperties":false},` +
	`"port":{"type":"integer","minimum":1,"maximum":65535},` +
	`"clock":{"type":"object","properties":{` +
	`"host":{"type":"string","minLength":1,"maxLength":64},` +
	`"port":{"type":"integer","minimum":1,"maximum":65535}` +
	`},"required":["host","port"],"additionalProperties":false},` +
	`"clockMaster":{"type":"boolean"},` +
	`"channel":{"enum":["both","left","right","mono"]},` +
	`"latencyMs":{"type":"integer","minimum":200,"maximum":5000},` +
	`"trimMs":{"type":"integer","minimum":-500,"maximum":500},` +
	`"trimUs":{"type":"integer","minimum":-500000,"maximum":500000},` +
	`"trims":{"type":"array","maxItems":16,"items":{"type":"object","properties":{` +
	`"outputId":{"type":"string","minLength":1,"maxLength":64},` +
	`"trimUs":{"type":"integer","minimum":-500000,"maximum":500000}` +
	`},"required":["outputId","trimUs"],"additionalProperties":false}},` +
	`"budgetUs":{"type":"integer","minimum":50,"maximum":20000},` +
	`"bitrateKbps":{"type":"integer","minimum":64,"maximum":510},` +
	`"pcm":{"type":"boolean"},` +
	`"members":{"type":"array","maxItems":8,"items":{"type":"string","minLength":1,"maxLength":64}},` +
	`"waitMs":{"type":"integer","minimum":0,"maximum":10000},` +
	`"autoLatency":{"type":"boolean"},` +
	`"autoBitrate":{"type":"boolean"},` +
	`"autoWait":{"type":"boolean"},` +
	`"tracking":{"type":"object","properties":{` +
	`"enabled":{"type":"boolean"},` +
	`"members":{"type":"array","maxItems":8,"items":{"type":"string","minLength":1,"maxLength":64}}` +
	`},"required":["enabled"],"additionalProperties":false}` +
	`},"required":["enabled"],"additionalProperties":false,` +
	`"if":{"properties":{"enabled":{"const":true}}},` +
	`"then":{"required":["groupId","role","latencyMs"],` +
	`"if":{"properties":{"role":{"const":"member"}}},"then":{"required":["leader"]}}}`

// MediaGroupState is media.group's state, from audiod's GroupStatus: numbers and tokens only (rule 8). members is the
// leader's view of each member. localSource is cadenced's own: this device plays a source of its own the group can
// carry (a url, file or stream, soloist, airplay, or an external session on the mixer such as a screen's player),
// not the group's stream and not a direct route; the server makes the latest device to raise it the group's leader.
const MediaGroupState = `{"type":"object","properties":{` +
	`"groupId":{"type":"string","maxLength":64},` +
	`"role":{"enum":["","leader","member"]},` +
	`"state":{"enum":["off","idle","connecting","syncing","buffering","playing","rejoining","failed"]},` +
	`"output":{"type":"object","properties":{` +
	`"id":{"type":"string","minLength":1,"maxLength":64},` +
	`"kind":{"enum":["speaker","hdmi","bluetooth","other"]},` +
	`"delayHintUs":{"type":"integer","minimum":0,"maximum":60000000}` +
	`},"required":["id","kind"],"additionalProperties":false},` +
	`"error":{"type":"string","maxLength":32},` +
	`"synced":{"type":"boolean"},` +
	`"clockErrorUs":{"type":"integer","minimum":0},` +
	`"queueMs":{"type":"integer","minimum":0},` +
	`"steerPpm":{"type":"integer"},` +
	`"rejoins":{"type":"integer","minimum":0},` +
	`"underruns":{"type":"integer","minimum":0},` +
	`"placementErrorUs":{"type":"integer"},` +
	`"latencyMs":{"type":"integer","minimum":0},` +
	`"bitrateKbps":{"type":"integer","minimum":0},` +
	`"waitMs":{"type":"integer","minimum":0},` +
	`"localSource":{"type":"boolean"},` +
	`"members":{"type":"array","maxItems":8,"items":{"type":"object","properties":{` +
	`"deviceId":{"type":"string","maxLength":64},` +
	`"state":{"enum":["off","idle","connecting","syncing","buffering","playing","rejoining","failed"]},` +
	`"connected":{"type":"boolean"},` +
	`"synced":{"type":"boolean"},` +
	`"clockErrorUs":{"type":"integer","minimum":0},` +
	`"queueMs":{"type":"integer","minimum":0},` +
	`"rejoins":{"type":"integer","minimum":0},` +
	`"placementErrorUs":{"type":"integer"}` +
	`},"additionalProperties":false}},` +
	`"tracking":{"type":"object","properties":{` +
	`"state":{"enum":["off","idle","tracking","needs_calibration","unsupported"]},` +
	`"members":{"type":"array","maxItems":8,"items":{"type":"object","properties":{` +
	`"deviceId":{"type":"string","maxLength":64},` +
	`"offsetUs":{"type":"integer"},` +
	`"ci95Us":{"type":"integer","minimum":0},` +
	`"cycles":{"type":"integer","minimum":0,"maximum":6},` +
	`"correctionUs":{"type":"integer","minimum":-5000,"maximum":5000},` +
	`"correctionId":{"type":"integer","minimum":0,"maximum":4294967295}` +
	`},"required":["deviceId","offsetUs","ci95Us","cycles"],"additionalProperties":false}}` +
	`},"required":["state","members"],"additionalProperties":false}` +
	`},"required":["state"],"additionalProperties":false}`

// MediaGroupLeader is where a member reaches its leader, or a device the group's clock master.
type MediaGroupLeader struct {
	Host string `json:"host"`
	Port int    `json:"port"`
}

// output kinds as media.group's state spells them
const (
	GroupOutputSpeaker   = "speaker"
	GroupOutputHDMI      = "hdmi"
	GroupOutputBluetooth = "bluetooth"
	GroupOutputOther     = "other"
)

// MediaGroupOutput is the output a device plays the group's stream through now. DelayHintUs is its own delay report,
// when it has one (BlueZ's MediaTransport1.Delay for bluetooth).
type MediaGroupOutput struct {
	ID          string `json:"id"`
	Kind        string `json:"kind"`
	DelayHintUs *int   `json:"delayHintUs,omitempty"`
}

// MediaGroupTrim is a calibration's trim for one output of a device; the member's trimUs is the fallback for an
// output with no entry.
type MediaGroupTrim struct {
	OutputID string `json:"outputId"`
	TrimUs   int    `json:"trimUs"`
}

// MediaGroupTrackingConfig enables ultrasonic live tracking. Members is the leader's allow-list from the server,
// containing only members whose capability round answered ok; it is empty on a member.
type MediaGroupTrackingConfig struct {
	Enabled bool     `json:"enabled"`
	Members []string `json:"members,omitempty"`
}

// MediaGroup is MediaGroupConfig as Go: the server marshals it, the device unmarshals it.
type MediaGroup struct {
	Enabled     bool                      `json:"enabled"`
	GroupID     string                    `json:"groupId,omitempty"`
	Role        string                    `json:"role,omitempty"`
	Leader      *MediaGroupLeader         `json:"leader,omitempty"`
	Port        int                       `json:"port,omitempty"`
	Channel     string                    `json:"channel,omitempty"`
	LatencyMs   int                       `json:"latencyMs,omitempty"`
	TrimMs      int                       `json:"trimMs,omitempty"`
	TrimUs      int                       `json:"trimUs,omitempty"`
	Trims       []MediaGroupTrim          `json:"trims,omitempty"`
	BudgetUs    int                       `json:"budgetUs,omitempty"`
	BitrateKbps int                       `json:"bitrateKbps,omitempty"`
	PCM         bool                      `json:"pcm,omitempty"`
	Members     []string                  `json:"members,omitempty"`
	WaitMs      int                       `json:"waitMs,omitempty"`
	AutoLatency bool                      `json:"autoLatency,omitempty"`
	AutoBitrate bool                      `json:"autoBitrate,omitempty"`
	AutoWait    bool                      `json:"autoWait,omitempty"`
	Clock       *MediaGroupLeader         `json:"clock,omitempty"`
	ClockMaster bool                      `json:"clockMaster,omitempty"`
	Tracking    *MediaGroupTrackingConfig `json:"tracking,omitempty"`
}

// MediaGroupMemberStatus is one member in MediaGroupStatus.
type MediaGroupMemberStatus struct {
	DeviceID         string `json:"deviceId"`
	State            string `json:"state"`
	Connected        bool   `json:"connected"`
	Synced           bool   `json:"synced"`
	ClockErrorUs     int    `json:"clockErrorUs"`
	QueueMs          int    `json:"queueMs"`
	Rejoins          int    `json:"rejoins"`
	PlacementErrorUs int    `json:"placementErrorUs"`
}

// MediaGroupTrackingMember is one member's smoothed offset and a suggested trim correction (never applied by audiod).
type MediaGroupTrackingMember struct {
	DeviceID     string `json:"deviceId"`
	OffsetUs     int    `json:"offsetUs"`
	Ci95Us       int    `json:"ci95Us"`
	Cycles       int    `json:"cycles"`
	CorrectionUs int    `json:"correctionUs,omitempty"`
	// CorrectionId names the correction's one pulse and every later snapshot of it, for exactly-once server application
	CorrectionID uint32 `json:"correctionId,omitempty"`
}

// MediaGroupTracking is the live tracker state. Members is always an array, including when empty.
type MediaGroupTracking struct {
	State   string                     `json:"state"`
	Members []MediaGroupTrackingMember `json:"members"`
}

// MediaGroupStatus is MediaGroupState as Go.
type MediaGroupStatus struct {
	GroupID          string                   `json:"groupId,omitempty"`
	Role             string                   `json:"role,omitempty"`
	State            string                   `json:"state"`
	Output           *MediaGroupOutput        `json:"output,omitempty"`
	Error            string                   `json:"error,omitempty"`
	Synced           bool                     `json:"synced"`
	ClockErrorUs     int                      `json:"clockErrorUs"`
	QueueMs          int                      `json:"queueMs"`
	SteerPpm         int                      `json:"steerPpm"`
	Rejoins          int                      `json:"rejoins"`
	Underruns        int                      `json:"underruns"`
	PlacementErrorUs int                      `json:"placementErrorUs"`
	LatencyMs        int                      `json:"latencyMs"`
	BitrateKbps      int                      `json:"bitrateKbps,omitempty"`
	WaitMs           int                      `json:"waitMs,omitempty"`
	LocalSource      bool                     `json:"localSource,omitempty"`
	Members          []MediaGroupMemberStatus `json:"members,omitempty"`
	Tracking         MediaGroupTracking       `json:"tracking"`
}

// GroupCalibrateCommand is media.group's one command, on a group's leader: an acoustic calibration of the group (every
// member plays a short chirp through its group playout, rounds times, at most its own level less 6 dB, and records
// its microphones, in memory only). the owner's, from the dashboard: a device refuses it in a voice turn (rule 7). args
// GroupCalibrateArgs: mode mics (the default: every member records its own microphones), listener (every member plays
// its chirps at its slots and those with a microphone record them too; the owner's browser measures the arrivals where
// they listen, and the answer comes at once with the schedule: code scheduled, startsInMs, runId, rounds, chirp, slots)
// or listener_result (the speakers' own measure of listener run runId, answered as mics mode's); boost names members
// whose chirps play gainDb louder. a calibration that ran answers MediaGroupCalibration; one refused before it ran
// fails with the code alone (not_leader, playing, busy, gated, no_capture, too_few, expired, refused, unavailable,
// timeout, failed).
const GroupCalibrateCommand = "calibrate"

// calibrate's modes
const (
	GroupCalibrateModeMics           = "mics"
	GroupCalibrateModeListener       = "listener"
	GroupCalibrateModeListenerResult = "listener_result"
)

// calibrate's bounds: a boost's gain (over -20 dBFS of the music input, so at most -6 dBFS: under the device's own
// level, never above it), and the slots a schedule carries (rounds x members, round-major)
const (
	GroupBoostMaxDb        = 14
	GroupCalibrateMaxSlots = 32
)

// GroupCalibrateArgs is the calibrate command's args schema: runId with mode listener_result alone, and required
// there; boost, toleranceUs and priors belong to a run being started, not a listener_result lookup.
const GroupCalibrateArgs = `{"type":"object","properties":{"mode":{"enum":["mics","listener","listener_result"]},` +
	`"boost":{"type":"object","maxProperties":8,"propertyNames":{"minLength":1,"maxLength":64},` +
	`"additionalProperties":{"type":"integer","minimum":0,"maximum":14}},` +
	`"runId":{"type":"integer","minimum":0,"maximum":4294967295},` +
	`"toleranceUs":{"type":"integer","minimum":0,"maximum":4000000000},` +
	`"priors":{"type":"object","maxProperties":8,"propertyNames":{"minLength":1,"maxLength":64},` +
	`"additionalProperties":{"type":"object","properties":{` +
	`"priorUs":{"type":"integer","minimum":-2000000000,"maximum":2000000000},` +
	`"priorSpanUs":{"type":"integer","minimum":0,"maximum":4000000000}` +
	`},"additionalProperties":false}}},"additionalProperties":false,` +
	`"if":{"properties":{"mode":{"const":"listener_result"}},"required":["mode"]},` +
	`"then":{"required":["runId"],"not":{"anyOf":[{"required":["boost"]},{"required":["priors"]},{"required":["toleranceUs"]}]}},` +
	`"else":{"not":{"required":["runId"]}}}`

// MediaGroupCalibratePrior is one member's output-latency estimate and search half-width, us.
type MediaGroupCalibratePrior struct {
	PriorUs     int64 `json:"priorUs,omitempty"`
	PriorSpanUs int64 `json:"priorSpanUs,omitempty"`
}

// MediaGroupCalibrateArgs is GroupCalibrateArgs as Go.
type MediaGroupCalibrateArgs struct {
	Mode        string                              `json:"mode,omitempty"`
	Boost       map[string]int                      `json:"boost,omitempty"`
	RunID       *uint32                             `json:"runId,omitempty"`
	ToleranceUs *uint32                             `json:"toleranceUs,omitempty"`
	Priors      map[string]MediaGroupCalibratePrior `json:"priors,omitempty"`
}

// the listener chirps: rounds x members slots, the leader first in every round, GroupListenerSlotMs apart (wider than
// any trim can correct, so a slot's chirp is never taken for its neighbour's), the first GroupListenerStartMs after the
// request. the sweep is the schedule's own; a schedule without one (a leader from before rounds) played the legacy
// sweep, one round
const (
	GroupListenerSlotMs    = 1200
	GroupListenerStartMs   = 1500
	GroupChirpF0Hz         = 800
	GroupChirpF1Hz         = 7000
	GroupChirpUs           = 250000
	GroupChirpFadeUs       = 10000
	GroupLegacyChirpF0Hz   = 1000
	GroupLegacyChirpF1Hz   = 6000
	GroupLegacyChirpUs     = 100000
	GroupLegacyChirpFadeUs = 5000
)

// MediaGroupCalibration is a calibration's result: code ok (every member measured: the offsets apply), incomplete
// (some member could not be measured; no trim applies) or inconsistent (the pairs disagree past 1 ms). each member's
// offsetUs is its output latency less the measured members' mean, its trim left out: its trim should be -offsetUs.
// the leader is members[0]. numbers, ids and tokens only (rule 8)
type MediaGroupCalibration struct {
	Code       string                        `json:"code"`
	ResidualUs int                           `json:"residualUs"`
	Members    []MediaGroupCalibrationMember `json:"members"`
	// listener mode (code scheduled): the first chirp starts startsInMs after the answer was made, each slot offsetMs
	// after it (the leader's of round 0 first, at 0); runId is what listener_result takes. rounds and chirp are absent
	// from a leader before rounds (one round, the legacy sweep)
	StartsInMs int                         `json:"startsInMs,omitempty"`
	RunID      uint32                      `json:"runId,omitempty"`
	Rounds     int                         `json:"rounds,omitempty"`
	Chirp      *MediaGroupChirp            `json:"chirp,omitempty"`
	Probe      *MediaGroupProbe            `json:"probe,omitempty"`
	Slots      []MediaGroupCalibrationSlot `json:"slots,omitempty"`
}

// MediaGroupProbe is a listener calibration's coded probe; kind is gold.
type MediaGroupProbe struct {
	Kind     string `json:"kind"`
	BandLoHz int    `json:"bandLoHz"`
	BandHiHz int    `json:"bandHiHz"`
	FadeUs   int    `json:"fadeUs"`
}

// MediaGroupChirp is the sweep the members play: exponential from f0Hz to f1Hz, raised-cosine fades.
type MediaGroupChirp struct {
	F0Hz       int `json:"f0Hz"`
	F1Hz       int `json:"f1Hz"`
	DurationUs int `json:"durationUs"`
	FadeUs     int `json:"fadeUs"`
}

// MediaGroupCalibrationSlot is one member's chirp of one round in a listener calibration.
type MediaGroupCalibrationSlot struct {
	DeviceID string `json:"deviceId"`
	OffsetMs int    `json:"offsetMs"`
	Round    int    `json:"round"`
	Code     uint32 `json:"code"`
}

// MediaGroupCalibrationMember is one member of a calibration: code ok, no_self, isolated, unstable (its rounds
// disagree), missed (its own coded probe was not found), no_answer, offline, or its own refusal (busy, gated,
// no_capture, muted, unsynced, epoch). spreadUs is how far its rounds spread, ci95Us the 95% interval's half-width,
// rounds the fewest it kept, micChannels the microphone channels it analysed.
type MediaGroupCalibrationMember struct {
	DeviceID    string  `json:"deviceId"`
	Code        string  `json:"code"`
	OffsetUs    int     `json:"offsetUs"`
	Confidence  float64 `json:"confidence"`
	SpreadUs    int     `json:"spreadUs,omitempty"`
	Ci95Us      int     `json:"ci95Us"`
	Rounds      int     `json:"rounds,omitempty"`
	MicChannels int     `json:"micChannels,omitempty"`
	Ultrasonic  string  `json:"ultrasonic,omitempty"`
}
